class Solution { public String reorganizeString(String s){int[] counts=new int[26];for(char c:s.toCharArray())counts[c-'a']++;PriorityQueue<int[]> heap=new PriorityQueue<>((a,b)->a[1]!=b[1]?Integer.compare(b[1],a[1]):Integer.compare(a[0],b[0]));for(int c=0;c<26;c++)if(counts[c]>0)heap.offer(new int[]{c,counts[c]});StringBuilder answer=new StringBuilder();int[] previous=null;while(!heap.isEmpty()){int[] current=heap.poll();answer.append((char)('a'+current[0]));if(previous!=null&&previous[1]>0)heap.offer(previous);current[1]--;previous=current;}return previous!=null&&previous[1]>0?"":answer.toString();} }
